class NaamRequest(TypedDict, total=False):
    """Two names to match star to star, and the readings they are matched under. Naam milan needs no chart, so this is the whole request."""

    bride: Required[str]
    """The bride's name, in Devanagari or in the Latin scheme `rules.name.latin` declares."""

    groom: Required[str]
    """The groom's."""

    rules: NaamRules
    """How the names are read and matched; the sources' own when left out."""


class NumerologyRequest(TypedDict, total=False):
    """A name and a birth date, and the readings they are taken under. Numerology reads no sky, so this is the whole request."""

    date: Required[BirthDate]
    """The Gregorian birth date, `{"year", "month", "day"}`."""

    name: Required[str]
    """The name, in the 26 Latin letters."""

    rules: NumerologyRequestRules
    """The readings; the sources' own when left out, and `"BASELINE"` names `NumerologyRules::baseline`, every reading the baseline engine takes."""


